-- AD_Spotlight: the Spotlight Layouts on the New Layout page, whole layouts
-- players made and shared for anyone to start from, and their new versions.
-- Each is a share string the Import page also takes; a card imports it and
-- opens the new layout. They use WoW Forever's spells, so only Forever lists them.
local ADDON, NS = ...

local SP = {}
NS.Spotlight = SP

-- { key, title, maker, class, desc, image, text, notes, link, linkLabel }:
-- maker and class put a maker's packs on one Home card. image is a
-- screenshot of the layout (2:1, in Textures\Spotlight); without one the card
-- draws the layout from text, its share string. notes say what the newest
-- string changed. A new version is a new string with a newer date
-- (tools\spotlight_pack.lua --stamp): the date decides who is offered it, and
-- no version number is shown. link: where the maker shares more (their OK
-- given), shown small on the card as linkLabel and copied from a popup, since
-- an addon cannot open a URL.
SP.IMG = "Interface\\AddOns\\" .. ADDON .. "\\Textures\\Spotlight\\"
SP.EMITY_DISCORD = "https://discord.gg/hcWetj8gEb"

