-- What a pack's string holds, read once: its items' permanent IDs and its date.
SP.info = {}

-- A cheap fingerprint of a pack's string: its length and a sum over 64 of its
-- bytes (tools\gen_spotlight_index.lua computes the same).
function SP.Sum(text)
    local n, s = #text, 0
    local step = math.max(1, math.floor(n / 64))
    for k = 1, n, step do s = (s * 31 + text:byte(k)) % 2147483647 end
    return s
end

-- The packs' index (UI\AD_SpotlightIndex.lua, made offline): each pack's IDs,
-- date and preview fill SP.info and the preview cache, so the window decodes
-- no pack to show it (nine decodes were one long frame on its first open).
-- A pack whose string changed since the index was made decodes as before.
function SP.Seed()
    local idx = NS.SpotlightIndex
    if type(idx) ~= "table" then return end
    local LPm = NS.LayoutPreview
    for _, e in ipairs(SP.LIST) do
        local x = e.key and idx[e.key]
        if x and type(e.text) == "string" and x.len == #e.text and x.sum == SP.Sum(e.text) then
            local uids = {}
            for _, u in ipairs(x.uids or {}) do uids[u] = true end
            SP.info[e.key] = { uids = uids, at = x.at or 0 }
            if LPm and LPm.cache then LPm.cache[e.text] = x.parts end
        end
    end
    -- its copy lives in the caches now
    NS.SpotlightIndex = nil
end
SP.Seed()
function SP.Info(e)
    local info = SP.info[e.key]
    if info then return info end
    local payload = NS.Store.Peek(e.text)
    if not payload then return nil end
    info = { uids = {}, at = tonumber(payload.at) or 0 }
    for _, r in ipairs(payload.records or {}) do
        if type(r) == "table" and type(r.uid) == "string" and r.uid ~= "" then info.uids[r.uid] = true end
    end
    SP.info[e.key] = info
    return info
end

-- The date of the version the player has: the newest pack date on the items
-- that came from this pack (an import or an update writes it), nil when none
-- is here.
function SP.Mine(e)
    local info = SP.Info(e)
    if not info then return nil end
    local best
    NS.Store.EachRecord(function(_, r)
        if type(r.uid) == "string" and info.uids[r.uid] then
            local at = tonumber(r.imported) or 0
            if not best or at > best then best = at end
        end
    end)
    return best
end

function SP.Owned(e) return SP.Mine(e) ~= nil end

-- the player has this pack and the addon carries a newer version of it
function SP.HasUpdate(e)
    local info, mine = SP.Info(e), SP.Mine(e)
    return info ~= nil and mine ~= nil and info.at > mine
end

-- the Import page, on the update plan for the player's copy
function SP.Offer(e)
    if NS.Options and NS.Options.ImportOffer then NS.Options.ImportOffer(e.text) end
end

function SP.NotesText(e)
    return table.concat(e.notes or {}, " ")
end

-- Every layout of the player's that holds a pack's items older than the pack
-- the addon carries: { e, layoutId } each, packs in list order. Each layout is
-- judged by the newest pack date its own items carry, so a copy already
-- updated is left out while an older one is not. Forever only.
function SP.Updates()
    local out = {}
    if not NS.IsForever then return out end
    for _, e in ipairs(SP.LIST) do
        local info = SP.Info(e)
        if info then
            local newest = {}
            NS.Store.EachRecord(function(_, r)
                if type(r.uid) == "string" and info.uids[r.uid] then
                    local lay = (r.type == "layout") and r or NS.Store.LayoutOf(r)
                    local at = tonumber(r.imported) or 0
                    if lay and (newest[lay.id] == nil or at > newest[lay.id]) then newest[lay.id] = at end
                end
            end)
            local ids = {}
            for lid, at in pairs(newest) do
                if info.at > at then ids[#ids + 1] = lid end
            end
            table.sort(ids)
            for _, lid in ipairs(ids) do out[#out + 1] = { e = e, layoutId = lid } end
        end
    end
    return out
end

-- The player's layouts holding a pack's items (by the pack's key), by id.
function SP.LayoutsOf(key)
    local e
    for _, x in ipairs(SP.LIST) do
        if x.key == key then e = x end
    end
    local info = e and SP.Info(e)
    local out = {}
    if not info then return out end
    local set = {}
    NS.Store.EachRecord(function(_, r)
        if type(r.uid) == "string" and info.uids[r.uid] then
            local lay = (r.type == "layout") and r or NS.Store.LayoutOf(r)
            if lay and not set[lay.id] then
                set[lay.id] = true
                out[#out + 1] = lay.id
            end
        end
    end)
    table.sort(out)
    return out
end

-- The updates still waiting on Home: Later puts one off until the next version.
function SP.Pending()
    local u = NS.Store.UI()
    local later = u and u.packLater or {}
    local out = {}
    for _, up in ipairs(SP.Updates()) do
        local info = SP.Info(up.e)
        if later[up.e.key] ~= info.at then out[#out + 1] = up end
    end
    return out
end

function SP.Later(e)
    local u, info = NS.Store.UI(), SP.Info(e)
    if not (u and info) then return end
    u.packLater = u.packLater or {}
    u.packLater[e.key] = info.at
end

-- True once per pack version the player has not been shown yet, which it then
-- marks seen: the options window opens on Home for it (UI\AD_Home.lua).
function SP.TakeUnseen()
    local u = NS.Store.UI()
    if not u then return false end
    u.packSeen = u.packSeen or {}
    local any = false
    for _, up in ipairs(SP.Updates()) do
        local info = SP.Info(up.e)
        if u.packSeen[up.e.key] ~= info.at then
            u.packSeen[up.e.key] = info.at
            any = true
        end
    end
    return any
end

-- A maker's link, copied from a small popup (an addon cannot open a URL):
-- the address selected in a box for Ctrl+C, closed by Escape, Enter or a
-- click elsewhere.
function SP.ShowLink(url, label, anchor)
    local AT = NS.AT
    local COL = AT.COL
    if not SP.copy then
        local d = CreateFrame("Frame", "ArcAurasPackLinkCopy", UIParent, "BackdropTemplate")
        d:SetSize(320, 74)
        d:SetFrameStrata("FULLSCREEN_DIALOG")
        d:SetToplevel(true)
        AT.Skin(d, COL.panel, COL.arc)
        d.title = d:CreateFontString(nil, "OVERLAY")
        d.title:SetFont(NS.AT.FONT, 12, "")
        d.title:SetPoint("TOP", 0, -10)
        d.title:SetTextColor(COL.ink[1], COL.ink[2], COL.ink[3])
        local eb = CreateFrame("EditBox", nil, d, "BackdropTemplate")
        eb:SetSize(292, 22)
        eb:SetPoint("TOP", 0, -34)
        AT.Skin(eb, COL.well)
        eb:SetFont(NS.AT.FONT, 12, "")
        eb:SetTextInsets(6, 6, 0, 0)
        eb:SetTextColor(COL.ink[1], COL.ink[2], COL.ink[3])
        eb:SetAutoFocus(false)
        eb:SetScript("OnEscapePressed", function() d:Hide() end)
        eb:SetScript("OnEnterPressed", function() d:Hide() end)
        eb:SetScript("OnEditFocusLost", function() d:Hide() end)
        -- the box holds the link: typing over it puts it back
        eb:SetScript("OnTextChanged", function(s, user)
            if user and d.url then s:SetText(d.url) s:HighlightText() end
        end)
        tinsert(UISpecialFrames, "ArcAurasPackLinkCopy")
        d.box = eb
        SP.copy = d
    end
    local d = SP.copy
    d.url = url
    d.title:SetText((label and (label .. ": ") or "") .. "press Ctrl+C to copy")
    d:ClearAllPoints()
    d:SetPoint("CENTER", anchor or UIParent, "CENTER", 0, 0)
    d:Show()
    d:Raise()
    d.box:SetText(url)
    d.box:SetFocus()
    d.box:HighlightText()
end

-- The small link on a pack's card (Home and New Layout): its label in the
-- Discord color, a click opens the copy popup; `chip` boxes it, for a spot
-- over a picture. Nil for a pack with no link.
function SP.LinkButton(parent, t, chip)
    if not (t and t.link) then return nil end
    local AT = NS.AT
    local COL = AT.COL
    local b = CreateFrame("Button", nil, parent, chip and "BackdropTemplate" or nil)
    if chip then AT.Skin(b, COL.panel, COL.line) end
    b.fs = b:CreateFontString(nil, "OVERLAY")
    b.fs:SetFont(NS.AT.FONT, chip and 10 or 11, "")
    b.fs:SetPoint("CENTER")
    b.fs:SetText(t.linkLabel or "Link")
    b.fs:SetTextColor(COL.blurple[1], COL.blurple[2], COL.blurple[3])
    b:SetSize(math.ceil(b.fs:GetStringWidth() or 60) + (chip and 12 or 4), 16)
    b:SetScript("OnEnter", function(s)
        s.fs:SetTextColor(COL.ink[1], COL.ink[2], COL.ink[3])
    end)
    b:SetScript("OnLeave", function(s)
        s.fs:SetTextColor(COL.blurple[1], COL.blurple[2], COL.blurple[3])
    end)
    AT.Tooltip(b, t.linkLabel or "Link", "More packs from the maker. Click to copy the link.")
    b:SetScript("OnClick", function() SP.ShowLink(t.link, t.linkLabel, parent) end)
    return b
end

if NS.IsForever then
    for _, e in ipairs(SP.LIST) do
        NS.NewLayout.AddSpotlight({
            key = e.key, title = e.title, desc = e.desc, image = e.image, text = e.text,
            notes = e.notes, link = e.link, linkLabel = e.linkLabel,
            -- not `class`: a template's class keeps it to that class's New Layout page
            maker = e.maker, packClass = e.class,
            -- the string's date: a maker's newest pack
            at = function() local i = SP.Info(e) return i and i.at or 0 end,
            make = function() return NS.Store.ImportLayout(e.text) end,
            owned = function() return SP.Owned(e) end,
            hasUpdate = function() return SP.HasUpdate(e) end,
            update = function() SP.Offer(e) end,
        })
    end
end
